MOD=998244353

def main():
    it=iter(map(int,sys.stdin.buffer.read().split()))
    n=next(it)
    a=[next(it) for _ in range(n-1)]
    fac={}
    for i,v in enumerate(a):
        x=v; p=2
        while p*p<=x:
            while x%p==0:
                fac.setdefault(p,[0]*(n-1))[i]+=1
                x//=p
            p+=1
        if x>1:
            fac.setdefault(x,[0]*(n-1))[i]+=1
    ans=1
    for p,ds in fac.items():
        H=sum(ds)
        pw=[1]*(H+1)
        for j in range(1,H+1): pw[j]=pw[j-1]*p%MOD
        hit=[0]*(H+1); no=[0]*(H+1)
        for h in range(H+1):
            (hit if h==0 else no)[h]=pw[h]
        for d in ds:
            nh=[0]*(H+1); nn=[0]*(H+1)
            for h in range(H+1):
                if h+d<=H:
                    z=h+d; w=pw[z]
                    nh[z]=(nh[z]+hit[h]*w)%MOD
                    nn[z]=(nn[z]+no[h]*w)%MOD
                if d and h>=d:
                    z=h-d; w=pw[z]
                    nh[z]=(nh[z]+hit[h]*w)%MOD
                    if z==0: nh[z]=(nh[z]+no[h]*w)%MOD
                    else: nn[z]=(nn[z]+no[h]*w)%MOD
            hit,no=nh,nn
        ans=ans*sum(hit)%MOD
    print(ans)
main()

