import sys

MOD = 998244353
V = 100000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    phi = list(range(V + 1))
    for p in range(2, V + 1):
        if phi[p] == p:
            for x in range(p, V + 1, p):
                phi[x] -= phi[x] // p

    divisors = [[] for _ in range(V + 1)]
    for d in range(1, V + 1):
        for x in range(d, V + 1, d):
            divisors[x].append(d)

    accumulated = [0] * (V + 1)
    answer = 0
    weight = 1
    out = []

    for x in a:
        s = 0
        for d in divisors[x]:
            s += phi[d] * accumulated[d]
        answer = (answer * 2 + s) % MOD
        out.append(str(answer))

        for d in divisors[x]:
            v = accumulated[d] + weight
            accumulated[d] = v if v < MOD else v - MOD
        weight = (weight * 2) % MOD

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

