class Solution:
    def maxSubarrays(self, n: int, conflictingPairs):
        groups = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            groups[b].append((a, i))

        top_value = second_value = 0
        top_id = second_id = -1
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left, pair_id in groups[right]:
                if left > top_value:
                    second_value, second_id = top_value, top_id
                    top_value, top_id = left, pair_id
                elif left > second_value:
                    second_value, second_id = left, pair_id

            base += right - top_value
            if top_id != -1:
                gains[top_id] += top_value - second_value

        return base + max(gains)

