import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it); m = next(it); q = next(it)
    edges = []
    for _ in range(m):
        edges.append((next(it)-1, next(it)-1, next(it)))
    queries = []
    deleted = [False] * m
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted[e] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, w) in enumerate(edges):
        if not deleted[i]:
            dist[a][b] = w
            dist[b][a] = w

    # All roads which are never deleted are already available in the
    # final (reverse-time) state.
    for k in range(n):
        rowk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == INF:
                continue
            rowi = dist[i]
            for j in range(n):
                v = dik + rowk[j]
                if v < rowi[j]:
                    rowi[j] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            v = dist[query[1]][query[2]]
            answers.append(str(v if v < INF else -1))
        else:
            a, b, w = edges[query[1]]
            # Snapshot the old distances involving the endpoints.  Adding
            # one undirected edge permits a shortest path to use it once.
            ca = [dist[i][a] for i in range(n)]
            cb = [dist[i][b] for i in range(n)]
            ra = dist[a][:]
            rb = dist[b][:]
            for i in range(n):
                row = dist[i]
                via_a = ca[i] + w
                via_b = cb[i] + w
                for j in range(n):
                    v = via_a + rb[j]
                    if v < row[j]:
                        row[j] = v
                    v = via_b + ra[j]
                    if v < row[j]:
                        row[j] = v

    sys.stdout.write("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

