import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    upper = 10**30
    k = 2
    for _ in range(n):
        a, p, b, q = data[k:k + 4]
        k += 4
        machines.append((a, p, b, q))
        upper = min(upper, max(budget * a // p, budget * b // q))

    def minimum_cost(w, a, p, b, q):
        if w == 0:
            return 0
        best = 10**30
        # There is an optimum with fewer than b S-machines, or
        # fewer than a T-machines.
        for s in range(b):
            t = max(0, (w - a * s + b - 1) // b)
            best = min(best, s * p + t * q)
        for t in range(a):
            s = max(0, (w - b * t + a - 1) // a)
            best = min(best, s * p + t * q)
        return best

    def feasible(w):
        spent = 0
        for a, p, b, q in machines:
            spent += minimum_cost(w, a, p, b, q)
            if spent > budget:
                return False
        return True

    lo, hi = 0, upper
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

if __name__ == '__main__':
    main()

