class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        max_k = min(n, x)
        dp = [0] * (max_k + 1)
        dp[0] = 1

        for _ in range(n):
            nxt = [0] * (max_k + 1)
            for k, ways in enumerate(dp):
                if ways == 0:
                    continue
                if k > 0:
                    nxt[k] = (nxt[k] + ways * k) % mod
                if k < max_k:
                    nxt[k + 1] = (nxt[k + 1] + ways * (x - k)) % mod
            dp = nxt

        answer = 0
        score_choices = 1
        for k in range(1, max_k + 1):
            score_choices = score_choices * y % mod
            answer = (answer + dp[k] * score_choices) % mod
        return answer

