class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 1_000_000_007
        L = len(s)

        # less[j] counts prefixes already smaller than s with j one-bits;
        # eq[j] counts the single prefix still equal to s (indexed by its ones).
        less = [0] * (L + 1)
        equal = [0] * (L + 1)
        equal[0] = 1
        for ch in s:
            bit = ord(ch) - ord('0')
            new_less = [0] * (L + 1)
            new_equal = [0] * (L + 1)
            for j, v in enumerate(less):
                if v:
                    new_less[j] = (new_less[j] + v) % MOD
                    if j < L:
                        new_less[j + 1] = (new_less[j + 1] + v) % MOD
            if bit:
                for j, v in enumerate(equal):
                    if v:
                        new_less[j] = (new_less[j] + v) % MOD
            for j, v in enumerate(equal):
                if v and j + bit <= L:
                    new_equal[j + bit] = (new_equal[j + bit] + v) % MOD
            less, equal = new_less, new_equal

        answer = 0
        for ones in range(1, L + 1):
            value = ones
            operations = 0
            while value != 1:
                value = value.bit_count()
                operations += 1
            # A number with 'ones' set bits needs one initial operation,
            # followed by the operations needed to reduce 'ones' to one.
            if operations <= k - 1:
                answer = (answer + less[ones]) % MOD
        return answer

