import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    g = [x.decode() for x in data[1:1+n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for u in range(n):
        row = g[u]
        for v, ch in enumerate(row):
            if ch != '-':
                k = ord(ch) - 97
                outgoing[u][k].append(v)
                incoming[v][k].append(u)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    remaining = n * n
    for i in range(n):
        dist[i][i] = 0
        remaining -= 1
        heapq.heappush(heap, (0, i, i))
    for u in range(n):
        for v, ch in enumerate(g[u]):
            if ch != '-' and dist[u][v] == inf:
                dist[u][v] = 1
                remaining -= 1
                heapq.heappush(heap, (1, u, v))

    while heap:
        value, x, y = heapq.heappop(heap)
        if dist[x][y] != value:
            continue
        if remaining == 0:
            break
        new_value = value + 2
        for k in range(26):
            left = incoming[x][k]
            right = outgoing[y][k]
            for u in left:
                row = dist[u]
                for v in right:
                    if new_value < row[v]:
                        if row[v] == inf:
                            remaining -= 1
                        row[v] = new_value
                        heapq.heappush(heap, (new_value, u, v))

    out = []
    for row in dist:
        out.append(' '.join('-1' if x == inf else str(x) for x in row))
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

