    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        a = data[pos] - 1
        b = data[pos + 1] - 1
        pos += 2
        rows[a] |= 1 << b
        rows[b] |= 1 << a

    pivots = []
    rank = 0
    for col in range(n):
        chosen = None
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                chosen = i
                break
        if chosen is None:
            continue
        rows[rank], rows[chosen] = rows[chosen], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append((col, rank))
        rank += 1

    pivot_cols = {col for col, _ in pivots}
    free_cols = [col for col in range(n) if col not in pivot_cols]
    values = [0] * n

    for bit, free_col in enumerate(free_cols):
        values[free_col] |= 1 << bit
        for pivot_col, row in pivots:
            if (rows[row] >> free_col) & 1:
                values[pivot_col] |= 1 << bit

