from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        a = [v for row in grid for v in row]
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        tails = []

        for di, dj in dirs:
            t2 = array('H', [0]) * (n * m)
            t0 = array('H', [0]) * (n * m)
            ir = range(n - 1, -1, -1) if di == 1 else range(n)
            jr = range(m - 1, -1, -1) if dj == 1 else range(m)
            for i in ir:
                for j in jr:
                    x = i * m + j
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        y = ni * m + nj
                        if a[x] == 2:
                            t2[x] = 1 + t0[y]
                        elif a[x] == 0:
                            t0[x] = 1 + t2[y]
                    else:
                        if a[x] == 2:
                            t2[x] = 1
                        elif a[x] == 0:
                            t0[x] = 1
            tails.append((t2, t0))

        ans = 0
        for d, (di, dj) in enumerate(dirs):
            dp = array('H', [0]) * (n * m)
            nd = (d + 1) % 4
            ndi, ndj = dirs[nd]
            t2, t0 = tails[nd]
            ir = range(n) if di == 1 else range(n - 1, -1, -1)
            jr = range(m) if dj == 1 else range(m - 1, -1, -1)
            for i in ir:
                for j in jr:
                    x = i * m + j
                    v = a[x]
                    if v == 1:
                        dp[x] = 1
                    else:
                        pi, pj = i - di, j - dj
                        if 0 <= pi < n and 0 <= pj < m:
                            z = dp[pi * m + pj]
                            if z and ((v == 2 and z & 1) or (v == 0 and not (z & 1))):
                                dp[x] = z + 1
                    z = dp[x]
                    if z > ans:
                        ans = z
                    ni, nj = i + ndi, j + ndj
                    if z and 0 <= ni < n and 0 <= nj < m:
                        y = ni * m + nj
                        cand = z + (t2[y] if z & 1 else t0[y])
                        if cand > ans:
                            ans = cand
        return ans

