from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        def completions(odds: int, evens: int, previous: int) -> int:
            length = odds + evens
            if length == 0:
                return 1
            required = 1 - previous
            if length % 2 == 0:
                if odds != evens:
                    return 0
            else:
                required_count = odds if required == 1 else evens
                if required_count != (length + 1) // 2:
                    return 0
            return min(CAP, fact[odds] * fact[evens])

        unused = [True] * (n + 1)
        odds = (n + 1) // 2
        evens = n // 2
        result = []
        previous = None

        for _ in range(n):
            chosen = 0
            for value in range(1, n + 1):
                parity = value & 1
                if not unused[value] or (previous is not None and parity == previous):
                    continue
                count = completions(
                    odds - parity,
                    evens - (1 - parity),
                    parity,
                )
                if count < k:
                    k -= count
                else:
                    chosen = value
                    break

            if chosen == 0:
                return []
            result.append(chosen)
            unused[chosen] = False
            if chosen & 1:
                odds -= 1
            else:
                evens -= 1
            previous = chosen & 1

        return result

