class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = [0] * m
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = (p10[i-1] * 10) % k
        for i in range(m):
            j = n - 1 - i
            coeff[i] = (p10[j] + (p10[i] if i != j else 0)) % k
        dp = [0] * (m + 1)
        dp[m] = 1
        full = (1 << k) - 1
        for i in range(m - 1, -1, -1):
            c = coeff[i]
            mask = 0
            for d in range(10):
                shift = (d * c) % k
                x = dp[i+1]
                if shift:
                    x = ((x << shift) | (x >> (k-shift))) & full
                mask |= x
            dp[i] = mask
        ans = []
        rem = 0
        for i, c in enumerate(coeff):
            lo = 1 if i == 0 else 0
            for d in range(9 if i == 0 else 9, lo-1, -1):
                need = (-rem - d*c) % k
                if (dp[i+1] >> need) & 1:
                    ans.append(str(d)); rem = (rem + d*c) % k; break
        left = ''.join(ans)
        return left + (left[:-1] if n % 2 else left)[::-1]

