class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        up = [nxt]
        first_cost = [0] * n
        for i, q in enumerate(nxt):
            if q < n:
                first_cost[i] = nums[i] * (q - i - 1) - (pref[q] - pref[i + 1])
        costs = [first_cost]

        for _ in range(1, levels):
            old_up = up[-1]
            old_cost = costs[-1]
            new_up = [n] * n
            new_cost = [0] * n
            for i in range(n):
                q = old_up[i]
                if q < n:
                    new_up[i] = old_up[q]
                    new_cost[i] = old_cost[i] + old_cost[q]
                else:
                    new_up[i] = n
                    new_cost[i] = old_cost[i]
            up.append(new_up)
            costs.append(new_cost)

        def cost(l, r):
            pos = l
            result = 0
            for j in range(levels - 1, -1, -1):
                q = up[j][pos]
                if q <= r:
                    result += costs[j][pos]
                    pos = q
            result += nums[pos] * (r - pos) - (pref[r + 1] - pref[pos + 1])
            return result

        answer = 0
        for l in range(n):
            lo, hi = l, n
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if cost(l, mid - 1) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - l
        return answer

