from functools import cmp_to_key


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = []
    pos = 2
    for _ in range(n):
        funcs.append((data[pos], data[pos + 1]))
        pos += 2

    # For two functions i,j, i should be outer to j iff
    # (Ai-1)/Bi >= (Aj-1)/Bj.  Process in the reverse order.
    def compare(x, y):
        cross = (x[0] - 1) * y[1] - (y[0] - 1) * x[1]
        if cross < 0:
            return -1
        if cross > 0:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))

    impossible = -10**100
    dp = [impossible] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for used in range(k, 0, -1):
            candidate = a * dp[used - 1] + b
            if candidate > dp[used]:
                dp[used] = candidate

    print(dp[k])


