class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first, middle, last = p.split('*')

        def next_occurrences(pattern):
            m = len(pattern)
            hit = [False] * (n + 1)
            if m == 0:
                for i in range(n + 1):
                    hit[i] = True
            elif m <= n:
                prefix = [0] * m
                j = 0
                for i in range(1, m):
                    while j and pattern[i] != pattern[j]:
                        j = prefix[j - 1]
                    if pattern[i] == pattern[j]:
                        j += 1
                    prefix[i] = j

                j = 0
                for i, ch in enumerate(s):
                    while j and ch != pattern[j]:
                        j = prefix[j - 1]
                    if ch == pattern[j]:
                        j += 1
                    if j == m:
                        hit[i - m + 1] = True
                        j = prefix[j - 1]

            nxt = [n + 1] * (n + 2)
            for i in range(n, -1, -1):
                nxt[i] = i if hit[i] else nxt[i + 1]
            return nxt

        first_next = next_occurrences(first)
        middle_next = next_occurrences(middle)
        last_next = next_occurrences(last)

        best = n + 1
        for start in range(n + 1):
            if first_next[start] != start:
                continue
            after_first = start + len(first)
            middle_start = middle_next[after_first]
            if middle_start > n:
                continue
            after_middle = middle_start + len(middle)
            last_start = last_next[after_middle]
            if last_start <= n:
                best = min(best, last_start + len(last) - start)

        return -1 if best == n + 1 else best

