    while p < min(len(S), len(T)) and S[p] == T[p]:
        p += 1
    S, T = S[p:], T[p:]

    q = 0
    while q < min(len(S), len(T)) and S[-1-q] == T[-1-q]:
        q += 1
    if q:
        S, T = S[:-q], T[:-q]

    if abs(len(S) - len(T)) > K:
        print("No")
        return

    if len(S) > len(T):
        S, T = T, S
    n, m = len(S), len(T)
    width = 2 * K + 3
    inf = K + 1

    prev = [inf] * width
    for j in range(min(m, K) + 1):
        prev[j + K] = j

    for i in range(1, n + 1):
        cur = [inf] * width
        minimum = inf
        for j in range(max(0, i - K), min(m, i + K) + 1):
            x = j - i + K
            if j == 0:
                value = i
            else:
                value = prev[x + 1] + 1
                candidate = cur[x - 1] + 1
                if candidate < value:
