                candidate = prev[x] + (S[i - 1] != T[j - 1])
                if candidate < value:
                    value = candidate
            cur[x] = value
            if value < minimum:
                minimum = value
        if minimum > K:
            print("No")
            return
        prev = cur

    print("Yes" if prev[m - n + K] <= K else "No")

