import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for v in range(p * p, limit, p):
                    is_prime[v] = False

        if is_prime[n] or is_prime[m]:
            return -1

        inf = 10 ** 18
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            digits = str(value)
            length = len(digits)
            for i, ch in enumerate(digits):
                digit = ord(ch) - ord('0')
                place = 10 ** (length - 1 - i)

                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

                if digit > 0:
                    nxt = value - place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

