class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for k in range(1, n):
            if k <= right:
                z[k] = min(right - k + 1, z[k - left])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] - 1 > right:
                left, right = k, k + z[k] - 1

        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            first_condition = z[i] >= i
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    lcp[j] = lcp[j + 1] + 1
                else:
                    lcp[j] = 0
                if not first_condition and lcp[j] >= j - i:
                    answer += 1
            if first_condition:
                answer += n - i - 1
        return answer

